import { test, expect } from '@playwright/test';

test.describe('Public Profile Page - Shared Information Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should display public profile page with shared information when logged in', async ({ page }) => {
    // Setup: Mock user authentication
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Setup: Mock user data
    await page.route('**/api/user/me', (route) => {
      route.continue();
    });

    // Mock response for user data
    await page.route('**/api/user/me', (route) => {
      route.continue();
    }, {
      status: 200,
      body: JSON.stringify({
        id: 1,
        username: 'johndoe',
        email: 'john@example.com',
        firstName: 'John',
        lastName: 'Doe',
        profilePicture: 'https://example.com/avatars/john.jpg',
        bio: 'Software Developer',
        location: 'New York, NY',
        website: 'https://johndoe.com',
        socialMedia: {
          twitter: '@johndoe',
          linkedin: 'linkedin.com/in/johndoe',
          github: 'johndoe/repo'
        }
      })
    });

    // Setup: Mock user role
    await page.route('**/api/user/me/role', (route) => {
      route.continue();
    }, {
      status: 200,
      body: JSON.stringify({
        role: 'user'
      })
    });

    // Verify page loads
    const profilePageTitle = page.getByRole('heading', { name: /public profile/i });
    await expect(profilePageTitle).toBeVisible();

    // Verify user name is displayed
    const userName = page.getByText(/John Doe/i);
    await expect(userName).toBeVisible();

    // Verify email is displayed
    const userEmail = page.getByText(/john@example.com/i);
    await expect(userEmail).toBeVisible();

    // Verify profile picture is displayed
    const profilePicture = page.getByRole('img', { name: /John Doe/i });
    await expect(profilePicture).toBeVisible();

    // Verify bio is displayed
    const userBio = page.getByText(/Software Developer/i);
    await expect(userBio).toBeVisible();

    // Verify location is displayed
    const userLocation = page.getByText(/New York, NY/i);
    await expect(userLocation).toBeVisible();

    // Verify website is displayed
    const userWebsite = page.getByText(/https://johndoe.com/i);
    await expect(userWebsite).toBeVisible();

    // Verify social media links are displayed
    const twitterLink = page.getByRole('link', { href: /twitter\.com\/\@johndoe/i });
    await expect(twitterLink).toBeVisible();

    const linkedinLink = page.getByRole('link', { href: /linkedin\.com\/in\/johndoe/i });
    await expect(linkedinLink).toBeVisible();

    const githubLink = page.getByRole('link', { href: /johndoe\.github\.com/i });
    await expect(githubLink).toBeVisible();

    // Verify user role is displayed
    const userRole = page.getByText(/user/i);
    await expect(userRole).toBeVisible();

    // Verify user has a public profile
    const publicProfileBadge = page.getByRole('img', { name: /public profile/i });
    await expect(publicProfileBadge).toBeVisible();

    // Verify user has a private profile option
    const privateProfileButton = page.getByRole('button', { name: /private profile/i });
    await expect(privateProfileButton).toBeVisible();

    // Verify user has a logout option
    const logoutButton = page.getByRole('button', { name: /logout/i });
    await expect(logoutButton).toBeVisible();
  });

  test('should display error when user is not logged in and cannot access shared information', async ({ page }) => {
    // Setup: Mock user not authenticated
    await page.route('**/api/auth/login', (route) => {
      route.abort();
    });

    // Setup: Mock user data
    await page.route('**/api/user/me', (route) => {
      route.abort();
    });

    // Setup: Mock error response
    await page.route('**/api/user/me', (route) => {
      route.abort();
    }, {
      status: 401,
      body: JSON.stringify({
        error: 'Unauthorized'
      })
    });

    // Verify error message is displayed
    const errorMessage = page.getByText(/unauthorized/i);
    await expect(errorMessage).toBeVisible();

    // Verify login button is visible
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Verify user is not logged in
    const userName = page.getByText(/John Doe/i);
    await expect(userName).not.toBeVisible();

    // Verify no shared information is displayed
    const userBio = page.getByText(/Software Developer/i);
    await expect(userBio).not.toBeVisible();

    // Verify no social media links are displayed
    const twitterLink = page.getByRole('link', { href: /twitter\.com\/\@johndoe/i });
    await expect(twitterLink).not.toBeVisible();

    const linkedinLink = page.getByRole('link', { href: /linkedin\.com\/in\/johndoe/i });
    await expect(linkedinLink).not.toBeVisible();

    const githubLink = page.getByRole('link', { href: /johndoe\.github\.com/i });
    await expect(githubLink).not.toBeVisible();

    // Verify user has a logout option
    const logoutButton = page.getByRole('button', { name: /logout/i });
    await expect(logoutButton).toBeVisible();
  });
});
